def ty_le_tang_gia(p):
    lines = C['lines'].copy()
    lines['order_date'] = pd.to_datetime(lines['order_date'])
    lines = lines[p.mask(lines['order_date'])]
    items = lines['item_name'].unique()
    tang_gia = []
    for item in items:
        prices = lines[lines['item_name'] == item]['unit_price'].drop_duplicates().sort_values()
        if len(prices) > 1:
            for i in range(len(prices) - 1):
                if prices.iloc[i+1] > prices.iloc[i]:
                    tang_gia.append(item)
                    break
    return pct(len(tang_gia), len(items))

