        return pd.Series(dtype='float64')
    lines = C['lines'][C['lines']['order_id'].isin(o['order_id'])]
    items_ke_don = C['items'][C['items']['prescription'] == True]
    lines_ke_don = lines.merge(items_ke_don, on='item_code', how='inner')
